      "explanation": "• 抗てんかん薬の鎮痛機序は薬物によって異なり、①Na+チャネルの不活性化による 神経細胞膜の安定化、②GABAA 受容体を介した Cl-チャネル開口による神経細胞 興奮の抑制、③L 型または T 型 Ca2+チャネルを介した神経細胞内への Ca2+流入 阻害による神経細胞興奮の抑制、④脳内の GABA 濃度上昇によるドパミン濃度上 昇、⑤脳内の GABA 濃度上昇による 5‒HT 代謝促進による下行性抑制系の賦活化、 などの薬理作用を示す。 • システマティックレビューによると、バルプロ酸ナトリウムやクロナゼパムは GABA を介した鎮痛、 カルバマゼピン、 ラモトリギン、 トピラマート、 ゾニサミド、 フェニトインは Na+チャネル遮断による鎮痛を主とするとされているが、その他 の Ca2+チャネルを介した作用も合わせて存在するなど、 その鎮痛機序は複合的と 考えられている。 • 例えば、トピラマートは電位依存性 Na+チャネルを遮断し、GABA 受容体の作用 を増強し、L 型 Ca2+チャネルを阻害することが示されている。",
