      "explanation": " 下行性疼痛抑制系では、大縫線核から起始するセロトニン作動性神経系、青斑核か ら起始するノルアドレナリン作動性神経系などが知られている。  大縫線核は中脳から脳幹の内側部に分布する細胞集団であり、 中脳水道周囲灰白質 からの入力を受けて脊髄の同側後側索を下行し、多数のμ，δオピオイド受容体が 存在している。  大縫線核は中脳水道周囲灰白質からオピオイドペプチドを介する入力を受けてお り、内因性オピオイドによって下行性疼痛抑制系が賦活し、抑制性シナプス伝達が 促進される。  ノルアドレナリン作動性神経系は青斑核から脊髄前側索を下行し、 脊髄後角の侵害 受容ニューロンを抑制する。  オピオイド鎮痛薬が中脳水道周囲灰白質に作用することによって下行抑制系が活 性化され、脊髄後角において鎮痛作用を示す。",
