      "explanation": "脳卒中後疼痛は視床の障害後に起こることが多く、脳卒中患者の 8~55%に生じ、有病率は 1〜 8％とされる。 脳卒中発症直後から数年後、 多くは数カ月後に生じ、 麻痺などの神経症状が軽快 する経過中に出現する。 麻痺側、もしくは神経症状があった側に一致して起こる激しい、持続的な痛みで、自発的な間 欠痛、痛覚過敏、アロディニアも見られる。外側延髄梗塞後では、病巣同側の顔面と反体側の 体幹・上下肢に影響を受ける可能性が高い。 脳卒中後疼痛に関しては神経ブロックの適応はない。肩関節周囲炎や末梢神経障害性疼痛など の末梢神経由来の痛みの要素が考えられる場合は、神経ブロックの適応となる場合もある。薬 物療法では、有効性が高いことが明らかである薬物はない。薬物療法に抵抗性の場合、ニュー ロモデュレーションを考慮する。",
