      "explanation": "重篤な合併症として、 硬膜外血腫、 脊髄虚血、 神経損傷、 骨髄炎、 髄膜炎・脊髄膿瘍、 椎間板 炎、 一過性馬尾症候群、 気脳症などが報告されている。 気脳症では、 突然の頭痛症状をきたす。 稀ではあるが、 四肢麻痺や対麻痺などの神経損傷、 髄膜炎・ 骨髄炎などの感染症、 医療用麻薬に よる遅発性呼吸抑制による不可逆的身体障害といった致命的合併症が発生する可能性がある1,2)。 硬膜外腔は血管が豊富で、多量の局所麻酔薬を投与すると血中濃度が上昇して局所麻酔薬中 毒を起こす可能性がある。特に仙骨硬膜外腔は静脈叢に富んでおり、注意を要する3)。 手技として、炎症の強い患者ではステロイド薬を添加することもある。粒子状ステロイド薬 の血管内注入による脊髄梗塞や脳梗塞の危険性を考慮すると、水溶性ステロイド薬を使用すべ きである 3,4)。 黄色靭帯は、硬膜外麻酔の実施に不可欠な抵抗消失法の解剖学的基礎を形成する。しかし、 黄色靭帯の解剖には個人差が大きく、 正中の間隙(midline gaps)が生じる可能性があり、 硬膜外 麻酔の実施に影響する可能性がある。黄色靭帯の隙間は頸部および高胸部レベルでは頻繁に見 られるため、これらのレベルでは硬膜外針先の位置確認に対する知覚可能な障壁として黄色靭 帯に常に頼ることはできないことが示されている。 硬膜穿刺後頭痛の治療では、 安静臥位・補液、 薬物療法のほか、 硬膜外自家血注入を行う。 十 分な効果を得るのに必要な自家血注入量については様々な報告があるが、 多くの報告では10〜 20mL である 5)。",
