      "explanation": "Moskowitz らは、三叉神経と頭蓋内・硬膜血管の関係に注目し、三叉神経節由来の C 線維が 硬膜の血管に分布していることを示した。さらに、三叉神経を電気的・化学的に刺激したとこ ろ、硬膜血管に神経原性炎症が起こることを明らかにした。そして、三叉神経血管系を介する 神経原性炎症を三叉神経血管説として提唱した。この説では、何らかの刺激により血管に分布 する三叉神経終末や軸索が興奮し、CGRPや substance P，neurokinin Aなどの神経ペプチド が遊離され、神経原性炎症（血管拡張、血漿蛋白の漏出、肥満細胞の脱顆粒）が起こる。順行性 の伝導は、三叉神経脊髄核に至り、さらに高次の中枢へと投射され、大脳皮質で痛みとして知 覚される。逆行性の伝導は、神経ペプチドの遊離が促進され血管拡張や神経原性炎症が広い範 囲に誘発される。CGRP は片頭痛における疼痛発生のメカニズムに大きく関与するペプチドで あると理解されている。",
